/** 按模型：`provider + model` 聚合的用量与估算成本（数据来自宿主会话事件折叠）。 */
import { useMemo, useState, type ReactNode } from 'react'
import { failureReasonOf } from '../core/api.ts'
import { channelColorOf, channelOf, costCellOf } from '../core/channels.ts'
import { fmtCalls, fmtDateTime, fmtRelative, fmtTokens } from '../core/format.ts'
import { CSV_MIME, JSON_MIME, downloadFile, exportFileName, toCsv, toJson, type ExportColumn } from '../core/export.ts'
import { dropEmptyRows, hiddenEmptyRowsText } from '../core/rows.ts'
import { CostSourceChip } from '../components/CostSourceChip.tsx'
import { COST_SOURCE_LABELS } from '../core/pricing.ts'
import type { Channel, ModelAggregateRow, ModelsResponse } from '../core/types.ts'
import styles from '../styles/shared.module.css'
import listStyles from '../styles/lists.module.css'
import exportStyles from '../styles/export.module.css'
import { t, useT } from '../core/i18n.ts'
import { Select } from '../components/ui/Select.tsx'
import { Button } from '../components/ui/Button.tsx'
import uiStyles from '../styles/ui.module.css'

const MODELS_PATH = '/dsh-key-usage/models'

type SortKey = 'tokensDesc' | 'callsDesc' | 'costDesc' | 'recent'

/** 导出列：取原始数值（金额、命中率不带单位），方便直接进表格做计算。 */
const EXPORT_COLUMNS: Array<ExportColumn<ModelAggregateRow>> = [
  { key: 'provider', labelKey: 'm.channelId', value: (row) => row.provider },
  { key: 'providerLabel', labelKey: 'common.channel', value: (row) => row.providerLabel },
  { key: 'model', labelKey: 'm.model', value: (row) => row.model },
  { key: 'calls', labelKey: 'common.calls', value: (row) => row.calls },
  { key: 'tokens', label: 'Tokens', value: (row) => row.tokens },
  { key: 'inputTokens', labelKey: 'c.input', value: (row) => row.buckets.inputTokens },
  { key: 'outputTokens', labelKey: 'c.output', value: (row) => row.buckets.outputTokens },
  { key: 'cacheReadTokens', labelKey: 'c.cacheRead', value: (row) => row.buckets.cacheReadTokens },
  { key: 'cacheHitRate', labelKey: 'c.hitRate', value: (row) => row.cacheHitRate },
  { key: 'cost', labelKey: 'c.costNative', value: (row) => row.cost },
  { key: 'costSource', labelKey: 's.costSource', value: (row) => row.costSource === undefined ? null : row.costSource },
  { key: 'costMode', labelKey: 'd.costMode', value: (row) => row.costMode },
  { key: 'sessionCount', labelKey: 'm.sessions', value: (row) => row.sessionCount },
  { key: 'lastTime', labelKey: 'm.lastActive', value: (row) => fmtDateTime(row.lastTime) },
]

export function ModelsTab(props: {
  data: ModelsResponse | null
  channels: Channel[]
  /** 下钻定位：只显示该模型（key = provider|model）；null = 不过滤 */
  focusModel?: string | null
  /** 下钻定位：只显示该通道；null = 不过滤 */
  focusProvider?: string | null
}): ReactNode {
  /** 取词：宿主切语言时重渲染 */
  const t = useT()
  const [query, setQuery] = useState('')
  const [channelFilter, setChannelFilter] = useState('ALL')
  const [sortKey, setSortKey] = useState<SortKey>('tokensDesc')
  const [nowMs] = useState(() => Date.now())
  const rows = props.data?.rows ?? []
  const focusModel = props.focusModel ?? null
  const focusProvider = props.focusProvider ?? null

  const visible = useMemo(() => {
    const keyword = query.trim().toLowerCase()
    const filtered = dropEmptyRows(rows, (row) => row.tokens).rows.filter((row) => {
      const haystack = (row.model + ' ' + row.provider + ' ' + row.providerLabel).toLowerCase()
      const matchesQuery = keyword === '' || haystack.includes(keyword)
      const matchesChannel = channelFilter === 'ALL' || row.provider === channelFilter
      const matchesFocusModel = focusModel === null || row.provider + '|' + row.model === focusModel
      const matchesFocusProvider = focusProvider === null || row.provider === focusProvider
      return matchesQuery && matchesChannel && matchesFocusModel && matchesFocusProvider
    })
    const sorters: Record<SortKey, (first: ModelAggregateRow, second: ModelAggregateRow) => number> = {
      tokensDesc: (first, second) => second.tokens - first.tokens,
      callsDesc: (first, second) => second.calls - first.calls,
      costDesc: (first, second) => (second.cost ?? 0) - (first.cost ?? 0),
      recent: (first, second) => (second.lastTime ?? 0) - (first.lastTime ?? 0),
    }
    return [...filtered].sort(sorters[sortKey])
  }, [rows, query, channelFilter, sortKey, focusModel, focusProvider])

  const totalTokens = rows.reduce((total, row) => total + row.tokens, 0)
  const hiddenEmpty = dropEmptyRows(rows, (row) => row.tokens).hidden

  /** 导出当前筛选与排序后的行（JSON 取整行，CSV 按固定列映射）。 */
  const exportRows = (format: 'csv' | 'json'): void => {
    if (format === 'csv') downloadFile(exportFileName('models', 'csv'), toCsv(visible, EXPORT_COLUMNS), CSV_MIME)
    else downloadFile(exportFileName('models', 'json'), toJson(visible), JSON_MIME)
  }

  if (props.data === null) {
    const reason = failureReasonOf(MODELS_PATH)
    return <div className={styles.empty}>{reason === null ? t('m.loading') : t('m.unavailable') + reason}</div>
  }

  return (
    <div>
      {props.data.coverage.status !== 'complete' && (
        <div className={styles.warning}>{coverageText(props.data.coverage.status, props.data.coverage.skippedSessions)}</div>
      )}
      <div className={listStyles.filterBar}>
        <input className={listStyles.searchInput} placeholder={t('m.search')} value={query} onChange={(event) => setQuery(event.target.value)} />
        <Select
          ariaLabel={t('s.filterChannel')}
          value={channelFilter}
          onChange={setChannelFilter}
          options={[{ value: 'ALL', labelKey: 's.allChannels' }, ...props.channels.map((channel) => ({ value: channel.provider, label: channel.displayName }))]}
        />
        <Select
          ariaLabel={t('s.sort')}
          value={sortKey}
          onChange={(next) => setSortKey(next as SortKey)}
          options={[
            { value: 'tokensDesc', labelKey: 's.sortTokensDesc' },
            { value: 'callsDesc', labelKey: 's.sortCalls' },
            { value: 'costDesc', labelKey: 's.sortCost' },
            { value: 'recent', labelKey: 'm.lastActive' },
          ]}
        />
        <span className={exportStyles.exportGroup}>
          <Button size="sm" disabled={visible.length === 0} onClick={() => exportRows('csv')}>{t('export.csv')}</Button>
          <Button size="sm" disabled={visible.length === 0} onClick={() => exportRows('json')}>{t('export.json')}</Button>
        </span>
      </div>

      <div className={uiStyles.tableScroll}><table className={styles.table + ' ' + listStyles.modelTable}>
        <thead>
          <tr><th>{t('m.model')}</th><th>{t('common.calls')}</th><th>Tokens</th><th>{t('m.share')}</th><th>{t('d.hitRate')}</th><th>{t('c.cost')}</th><th>{t('m.lastActive')}</th></tr>
        </thead>
        <tbody>
          {visible.map((row) => {
            const percent = totalTokens > 0 ? Math.round(row.tokens / totalTokens * 100) : 0
            const channel = channelOf(props.channels, row.provider)
            const costCell = costCellOf(channel, row)
            return (
              <tr key={row.provider + '|' + row.model}>
                <td>
                  <div className={listStyles.listTitle}>
                    <div>
                      <div className={listStyles.listMain}>{row.model === '' ? t('m.others') : row.model}</div>
                      <div className={listStyles.listSub}>
                        <span
                          className={styles.statusDot}
                          style={{ background: channelColorOf(props.channels, row.provider), marginRight: 4 }}
                        />
                        {row.providerLabel} · {row.sessionCount}{t('common.sessionSuffix')}
                      </div>
                    </div>
                  </div>
                </td>
                <td>{fmtCalls(row.calls)}</td>
                <td>{fmtTokens(row.tokens)}</td>
                <td>
                  <span className={listStyles.listBar}>
                    <i style={{ width: Math.max(2, percent) + '%', background: channelColorOf(props.channels, row.provider) }} />
                  </span> {percent}%
                </td>
                <td>{row.cacheHitRate === null ? '—' : row.cacheHitRate.toFixed(1) + '%'}</td>
                <td>{row.cost === null || channel?.costMode !== 'perToken'
                  ? <span className={styles.dim}>{costCell.text}</span>
                  : <>{costCell.text}{costCell.amount && <CostSourceChip source={row.costSource} partial={row.partial} />}</>}</td>
                <td>{fmtRelative(row.lastTime, nowMs)}</td>
              </tr>
            )
          })}
          {visible.length === 0 && <tr><td colSpan={7} className={styles.empty}>{t('m.empty')}</td></tr>}
        </tbody>
      </table></div>
      <div className={styles.statExtra}>
        {props.data.priced ? '' : t('s.noCost')}
      </div>
    </div>
  )
}

function coverageText(status: string, skipped: number): string {
  if (status === 'unavailable') return t('s.unavailable')
  return t('s.partial') + String(skipped) + t('s.partialTail')
}
